#!/data/data/com.termux/files/usr/bin/bash
# REPL_APPROVED_MOTION_FIT_v0.6.52: fit approved motion to adjustable analytical basis.
# Source-only Termux Git publication, immutable original model and walk clips.
set -Eeuo pipefail
CAMPAIGN=REPL_APPROVED_MOTION_FIT_v0.6.52
printf 'CAMPAIGN=%s
AUTHORITY=TERMUX_GIT_SOURCE_ONLY
CANONICAL_GLB_MUTATION=FORBIDDEN
' "$CAMPAIGN"
for bin in python3 git sha256sum; do command -v "$bin" >/dev/null || { echo "BLOCKED:MISSING:$bin"; exit 2; }; done
python3 -c 'import numpy,scipy' || { echo 'BLOCKED:NUMPY_SCIPY_REQUIRED'; exit 2; }
export REPL_ENTRY_SCRIPT="$(readlink -f "$0")"
printf 'ENTRY_SHA256=%s
' "$(sha256sum "$REPL_ENTRY_SCRIPT" | cut -d' ' -f1)"
T="$(mktemp -d "${TMPDIR:-/tmp}/repl-fit52-XXXXXXXX")"
trap 'rm -rf "$T"' EXIT
export REPL_PAYLOAD="$T"
